"""Exercise the complete phone brightness controller, including real scheduling/retry bodies.
Android and Root are boundary facades; this does not validate a phone backlight."""
from pathlib import Path
import os, subprocess, tempfile
ROOT=Path(__file__).resolve().parents[1]
JDK=Path(os.environ.get('JAVA_HOME','C:/Program Files/Android/openjdk/jdk-21.0.8'))/'bin'
